// 2025, mla, 2024
// Nice visual proof that 2025 = 45² = 
// (1+2+3+4+5+6+7+8+9)² = 1³+2³+3³+4³+5³+6³+7³+8³+9³

// No animation, no controls, just the pattern.

const int m0 = (1<<1)|(1<<4)|(1<<8)|(1<<13)|(1<<19)|(1<<26);
const int m1 = (1<<2)|(1<<11);
bool border(int i) {
  int m = m0;
  if (i >= 32) {
    m = m1;
    i -= 32;
  }
  return ((1<<i)&m) != 0;
}

int index(int i) {
  int res = 2;
  int m = m0;
  if (i >= 32) {
    m = m1; i -= 32; res = 0;
  }
  int v = m&~((1<<i)-1);
  while (v != 0) {
    res++;
    v &= v-1;
  }
  return 8-res;
}

vec3 background = vec3(0.5);

vec3 h2rgb(float h) {
  vec3 rgb = clamp( abs(mod(h*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
  return smoothstep(0.0,1.0,rgb);	
}

vec3 getcol(vec2 p, ivec2 ix, float px) {
  vec3 col = background;
  int mn = min(ix.x,ix.y);
  int mx = max(ix.x,ix.y);
  if (mn >= 0 && mx < 53 &&
      !border(ix.x) && !border(ix.y)) {
    vec3 pcol = h2rgb(float(8-index(mx))/9.0);
    float d = length(p)-0.4;
    col = mix(pcol, col, smoothstep(0.0,px,d));
    col = mix(vec3(0), col, smoothstep(0.0,1.2*px,abs(d)));
  }
  return col;
}

void mainImage(out vec4 fragColor, vec2 fragCoord ) {
    float N = 45.0+8.0;
    vec2 p = (fragCoord-0.5*iResolution.xy)/min(iResolution.x,iResolution.y);
    p *= 1.05;
    p += 0.5;
    p *= N;
    float px = fwidth(p.x);
    vec2 ix = floor(p);
    p -= ix;
    p -= 0.5;
    vec3 col = getcol(p,ivec2(ix),px);
    col = pow(col,vec3(0.4545));
    fragColor = vec4(col,1.0);
}
